# VCCI charts for ggplot2: theme, colour scales, number labels and fonts.
#
#   source("theme_vcci.R")
#   vcci_setup()                 # fonts, theme_vcci() as default, decimal comma; vcci_setup("en") for a decimal point
#   ggplot(d, aes(year, score, colour = city)) + geom_line() +
#     labs(title = "Hà Nội vượt TP.HCM từ năm 2024", caption = "Nguồn: VCCI, Khảo sát PCI 2025")
#
# Brand guide, section 08: at most six series, in the order of vcci_series; Drum Gold only marks one value and always
# carries its label (vcci_highlight); bar and column axes start at zero; label series directly; cite the source
# (caption) under every chart. Scales: scale_colour_vcci() / scale_fill_vcci() for series; *_vcci_seq() for ordered
# values (light = low); *_vcci_div() around a reference (Bronze = below, Ivory = at, Blue = above).
# Needs ggplot2 (>= 3.5; 4.0 adds default geom colours and palettes through the theme), scales, systemfonts.

vcci_colours <- c("VCCI Blue" = "#264896", "Sky" = "#8FA6D6", "Drum Bronze" = "#CC713C", "Slate" = "#5C6478", "Bronze 20" = "#F2B18E", "Deep Navy" = "#0B1A4F", "Drum Gold" = "#FFCD00", "Ink" = "#161A26", "Stone" = "#E6E1D5", "Ivory" = "#F4F0E6", "Paper" = "#FBF9F4", "Blue Tint" = "#E7ECF6", "Muted" = "#BABFCC")
vcci_series <- c("#264896", "#8FA6D6", "#CC713C", "#5C6478", "#F2B18E", "#0B1A4F")   # in this order; at most six
vcci_sequential <- c("#CEDEFD", "#A9C0EC", "#8FA6D6", "#6D8BC8", "#5474B7", "#3D5EA7", "#264896")
vcci_sequential_5 <- c("#CEDEFD", "#8FA6D6", "#5474B7", "#264896", "#041C61")
vcci_diverging <- c("#9A4A15", "#CE7440", "#F2B18E", "#F4F0E6", "#A9C0EC", "#6D8BC8", "#3D5EA7")
vcci_highlight_colours <- list(focus = "#FFCD00", context = "#264896", muted = "#BABFCC")
vcci_font <- list(display = "Lora", text = "Be Vietnam Pro")

# Lora and Be Vietnam Pro: installed fonts first, then the quarto-vcci extension (_extensions/[owner/]vcci-*/fonts) or the
# brand system (brand-assets/03_Fonts) in this folder or up to four above, or fonts_dir.
vcci_fonts <- function(fonts_dir = NULL) {
  have <- function(f) f %in% c(systemfonts::system_fonts()$family, systemfonts::registry_fonts()$family)
  dirs <- c(fonts_dir, Sys.getenv("VCCI_FONTS"))
  d <- normalizePath(getwd(), winslash = "/")
  for (i in 1:5) {
    dirs <- c(dirs, Sys.glob(file.path(d, "_extensions", c("*", "*/*"), "fonts")), Sys.glob(file.path(d, "brand-assets", "03_Fonts", "*")))
    d <- dirname(d)
  }
  dirs <- dirs[nzchar(dirs) & dir.exists(dirs)]
  find <- function(file) { p <- file.path(dirs, file); p[file.exists(p)][1] }
  if (!have(vcci_font$text)) {
    r <- find("BeVietnamPro-Regular.ttf")
    if (!is.na(r)) systemfonts::register_font(vcci_font$text, plain = r, bold = find("BeVietnamPro-SemiBold.ttf"),
                                              italic = r, bolditalic = find("BeVietnamPro-SemiBold.ttf"))
  }
  if (!have(vcci_font$display)) {
    r <- find("Lora-Regular.ttf")
    if (!is.na(r)) systemfonts::register_font(vcci_font$display, plain = r, bold = find("Lora-SemiBold.ttf"),
                                              italic = find("Lora-Italic.ttf"), bolditalic = find("Lora-SemiBoldItalic.ttf"))
  }
  invisible(have(vcci_font$text) && have(vcci_font$display))
}

# Numbers as written in the document's language: 12.500,5 (vi) or 12,500.5 (en)
label_vcci <- function(accuracy = NULL, suffix = "", prefix = "", scale = 1, lang = getOption("vcci.lang", "vi")) {
  scales::label_number(accuracy = accuracy, suffix = suffix, prefix = prefix, scale = scale,
                       decimal.mark = if (lang == "vi") "," else ".", big.mark = if (lang == "vi") "." else ",")
}
label_vcci_percent <- function(accuracy = 1, lang = getOption("vcci.lang", "vi"))
  label_vcci(accuracy = accuracy, suffix = "%", scale = 100, lang = lang)

theme_vcci <- function(base_size = 8.5, base_family = vcci_font$text, title_family = vcci_font$display) {
  pt <- 96 / 72 / ggplot2::.pt   # line widths below are in points (R draws lwd 1 as 1/96 inch)
  th <- ggplot2::theme_minimal(base_size = base_size, base_family = base_family) +
    ggplot2::theme(
      text = ggplot2::element_text(colour = vcci_colours[["Ink"]]),
      plot.title = ggplot2::element_text(family = title_family, colour = vcci_colours[["VCCI Blue"]], size = base_size * 11 / 8.5,
                                         hjust = 0, margin = ggplot2::margin(b = 6)),
      plot.subtitle = ggplot2::element_text(colour = vcci_colours[["Slate"]], hjust = 0, margin = ggplot2::margin(b = 8)),
      plot.caption = ggplot2::element_text(colour = vcci_colours[["Slate"]], size = base_size * 7.5 / 8.5, hjust = 0,
                                           margin = ggplot2::margin(t = 8)),
      plot.title.position = "plot", plot.caption.position = "plot",
      axis.text = ggplot2::element_text(colour = vcci_colours[["Slate"]], size = base_size * 8 / 8.5),
      axis.title = ggplot2::element_text(colour = vcci_colours[["Slate"]]),
      axis.line.x = ggplot2::element_line(colour = vcci_colours[["Slate"]], linewidth = 0.8 * pt),
      axis.ticks.x = ggplot2::element_line(colour = vcci_colours[["Slate"]], linewidth = 0.8 * pt),
      axis.ticks.y = ggplot2::element_blank(),
      axis.ticks.length.x = ggplot2::unit(3, "pt"),
      panel.grid.major.y = ggplot2::element_line(colour = vcci_colours[["Stone"]], linewidth = 0.5 * pt),
      panel.grid.major.x = ggplot2::element_blank(), panel.grid.minor = ggplot2::element_blank(),
      panel.background = ggplot2::element_blank(),
      plot.background = ggplot2::element_rect(fill = "white", colour = NA),
      legend.position = "top", legend.justification = "left", legend.title = ggplot2::element_blank(),
      legend.text = ggplot2::element_text(colour = vcci_colours[["Ink"]], size = base_size * 8 / 8.5),
      legend.key.size = ggplot2::unit(9, "pt"), legend.margin = ggplot2::margin(0, 0, 0, 0),
      strip.text = ggplot2::element_text(colour = vcci_colours[["Ink"]], face = "bold", hjust = 0)
    )
  if (utils::packageVersion("ggplot2") >= "4.0.0") {
    # defaults for geoms and scales: VCCI Blue marks, value labels in Lora Blue, series and ordered colours
    th <- th + ggplot2::theme(
      geom = ggplot2::element_geom(ink = vcci_colours[["VCCI Blue"]], paper = "white", accent = vcci_colours[["VCCI Blue"]],
                                   fill = vcci_colours[["VCCI Blue"]], linewidth = 1.8 * pt, borderwidth = 0.5 * pt,
                                   family = title_family, fontsize = base_size),
      palette.colour.discrete = vcci_series, palette.fill.discrete = vcci_series,
      palette.colour.continuous = vcci_sequential, palette.fill.continuous = vcci_sequential)
  }
  th
}

vcci_pick <- function(colours, n) colours[unique(round(seq(1, length(colours), length.out = n)))]
vcci_series_pal <- function(n) {
  if (n > length(vcci_series)) stop("VCCI charts use at most ", length(vcci_series), " series: group the smallest or use small multiples")
  vcci_series[seq_len(n)]
}
vcci_seq_pal <- function(n) if (n == 5) vcci_sequential_5 else vcci_pick(vcci_sequential, n)
vcci_div_pal <- function(n) vcci_pick(vcci_diverging, n)

scale_colour_vcci <- function(...) ggplot2::discrete_scale("colour", palette = vcci_series_pal, ...)
scale_fill_vcci <- function(...) ggplot2::discrete_scale("fill", palette = vcci_series_pal, ...)
# ordered classes (discrete): up to 7; continuous values: *_c
scale_colour_vcci_seq <- function(...) ggplot2::discrete_scale("colour", palette = vcci_seq_pal, ...)
scale_fill_vcci_seq <- function(...) ggplot2::discrete_scale("fill", palette = vcci_seq_pal, ...)
scale_colour_vcci_div <- function(...) ggplot2::discrete_scale("colour", palette = vcci_div_pal, ...)
scale_fill_vcci_div <- function(...) ggplot2::discrete_scale("fill", palette = vcci_div_pal, ...)
scale_colour_vcci_seq_c <- function(...) ggplot2::scale_colour_gradientn(colours = vcci_sequential, ...)
scale_fill_vcci_seq_c <- function(...) ggplot2::scale_fill_gradientn(colours = vcci_sequential, ...)
scale_colour_vcci_div_c <- function(..., midpoint = 0) ggplot2::scale_colour_gradientn(
  colours = vcci_diverging, rescaler = function(x, ...) scales::rescale_mid(x, mid = midpoint), ...)
scale_fill_vcci_div_c <- function(..., midpoint = 0) ggplot2::scale_fill_gradientn(
  colours = vcci_diverging, rescaler = function(x, ...) scales::rescale_mid(x, mid = midpoint), ...)

# Colours for one highlighted value: Drum Gold for the chosen, VCCI Blue (or vcci_highlight_colours$muted) for the rest.
#   ggplot(d, aes(year, score, fill = vcci_highlight(year == 2025))) + geom_col() + scale_fill_identity()
vcci_highlight <- function(selected, others = vcci_highlight_colours$context)
  ifelse(selected, vcci_highlight_colours$focus, others)

# knitr device: SVG for Typst (vector, text set in the document's fonts), PNG at 300 dpi for Word
vcci_knitr <- function() {
  if (!isTRUE(getOption("knitr.in.progress"))) return(invisible())
  to <- knitr::pandoc_to()
  if (!is.null(to) && grepl("typst", to)) knitr::opts_chunk$set(dev = "svglite")
  else knitr::opts_chunk$set(dev = "ragg_png", dpi = 300)
}

vcci_setup <- function(lang = "vi", fonts_dir = NULL) {
  if (!vcci_fonts(fonts_dir)) warning("theme_vcci: Lora and Be Vietnam Pro not found; install them or pass fonts_dir")
  options(vcci.lang = lang, OutDec = if (lang == "vi") "," else ".")   # OutDec: default axis labels and inline numbers
  ggplot2::theme_set(theme_vcci())
  if (utils::packageVersion("ggplot2") < "4.0.0") {
    ggplot2::update_geom_defaults("text", list(family = vcci_font$display, colour = vcci_colours[["VCCI Blue"]], size = 8.5 / ggplot2::.pt))
    for (g in c("line", "path")) ggplot2::update_geom_defaults(g, list(colour = vcci_colours[["VCCI Blue"]], linewidth = 1.8 * 96 / 72 / ggplot2::.pt))
    ggplot2::update_geom_defaults("point", list(colour = vcci_colours[["VCCI Blue"]]))
    for (g in c("col", "bar", "area")) ggplot2::update_geom_defaults(g, list(fill = vcci_colours[["VCCI Blue"]]))
    options(ggplot2.discrete.colour = list(vcci_series), ggplot2.discrete.fill = list(vcci_series))
  }
  vcci_knitr()
  invisible()
}
